import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI } from "./api_service";

const COLORS = {
  primary: "#4F46E5",
  primaryLight: "#EEF2FF",
  success: "#10B981",
  successLight: "#DCFCE7",
  danger: "#EF4444",
  dangerLight: "#FEE2E2",
  warning: "#F59E0B",
  warningLight: "#FEF3C7",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0",
  background: "#F8FAFC",
  surface: "#FFFFFF"
};

const Dashboard = () => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {}
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());

  // ==================== SAFE PARSERS ====================
  const parseStats = (data = {}) => {
    const summary = data.summary || {};
    return {
      active_students: Number(data.active_students) || 0,
      present_today: Number(data.present_today) || 0,
      absent_today: Number(data.absent_today) || 0,
      summary: {
        unique_students: Number(summary.unique_students) || 0,
        total_records: Number(summary.total_records) || 0,
        avg_confidence: Number(summary.avg_confidence) || 0,
        max_confidence: Number(summary.max_confidence) || 0,
        min_confidence: Number(summary.min_confidence) || 0
      }
    };
  };

  const parseLog = (data) => {
    if (!data) return [];
    if (Array.isArray(data)) return data;
    if (Array.isArray(data.records)) return data.records;
    return [];
  };

  const parseStatus = (data) => {
    if (!data) return [];
    if (Array.isArray(data)) return data;
    if (Array.isArray(data.students)) return data.students;
    return [];
  };

  // ==================== LOAD DATA ====================
  const loadData = async () => {
    try {
      if (attendanceLog.length === 0) setLoading(true);

      const [statsRes, logRes, statusRes] = await Promise.all([
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      setStats(parseStats(statsRes?.data));
      setAttendanceLog(parseLog(logRes?.data));
      setStatusList(parseStatus(statusRes?.data));

      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      console.error("❌ Dashboard error:", err);
      setError("Erreur serveur - Backend non accessible");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    if (!autoRefresh) return;
    const timer = setInterval(loadData, 10000);
    return () => clearInterval(timer);
  }, [autoRefresh]);

  // ==================== STATS ====================
  const statCards = useMemo(() => {
    const total = stats.active_students;
    const present = stats.present_today;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      { id: "total", label: "Étudiants", value: total, icon: "👥", color: COLORS.primary, bgColor: COLORS.primaryLight },
      { id: "present", label: "Présents", value: present, icon: "✅", color: COLORS.success, bgColor: COLORS.successLight },
      { id: "absent", label: "Absents", value: stats.absent_today, icon: "❌", color: COLORS.danger, bgColor: COLORS.dangerLight },
      { id: "rate", label: "Taux", value: `${rate}%`, icon: "📈", color: "#8B5CF6", bgColor: "#F5F3FF" }
    ];
  }, [stats]);

  // ==================== LOADING ====================
  if (loading) {
    return (
      <div style={styles.loaderContainer}>
        <div style={styles.spinner}></div>
        <p style={styles.loaderText}>Chargement...</p>
      </div>
    );
  }

  return (
    <div style={styles.pageWrapper}>
      {/* HEADER */}
      <header style={styles.header}>
        <div>
          <h1 style={styles.title}>Dashboard</h1>
          <p style={styles.subtitle}>
            Mise à jour : {lastUpdated.toLocaleTimeString()}
          </p>
        </div>

        <div style={styles.actions}>
          <label>
            <input
              type="checkbox"
              checked={autoRefresh}
              onChange={() => setAutoRefresh(!autoRefresh)}
            />
            Auto-refresh
          </label>

          <button onClick={loadData} style={styles.refreshBtn}>
            🔄 Refresh
          </button>
        </div>
      </header>

      {error && <div style={styles.errorAlert}>{error}</div>}

      {/* STATS */}
      <div style={styles.statsGrid}>
        {statCards.map((c) => (
          <div key={c.id} style={styles.statCard}>
            <div style={{ ...styles.iconWrapper, backgroundColor: c.bgColor }}>
              {c.icon}
            </div>
            <div>
              <div>{c.label}</div>
              <strong>{c.value}</strong>
            </div>
          </div>
        ))}
      </div>

      {/* LOG TABLE */}
      <div style={styles.sectionCard}>
        <h3>Journal</h3>
        <table style={styles.table}>
          <thead>
            <tr>
              <th>Nom</th>
              <th>Heure</th>
              <th>Confiance</th>
            </tr>
          </thead>
          <tbody>
            {attendanceLog.length === 0 ? (
              <tr>
                <td colSpan="3">Aucune donnée</td>
              </tr>
            ) : (
              attendanceLog.map((row, i) => {
                const confidence = Number(row?.confidence) || 0;

                return (
                  <tr key={i}>
                    <td>{row?.name || row?.student || "Inconnu"}</td>
                    <td>{row?.timestamp || "—"}</td>
                    <td>{(confidence * 100).toFixed(1)}%</td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* STATUS */}
      <div style={styles.sectionCard}>
        <h3>Statut Classe</h3>
        <table style={styles.table}>
          <thead>
            <tr>
              <th>Nom</th>
              <th>Email</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {statusList.map((s, i) => (
              <tr key={i}>
                <td>{s?.name || "Inconnu"}</td>
                <td>{s?.email || "-"}</td>
                <td>
                  {s?.present ? "✅ Présent" : "❌ Absent"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// styles simplifiés (tes anciens sont OK aussi)
const styles = {
  pageWrapper: { padding: 20 },
  header: { display: "flex", justifyContent: "space-between" },
  title: { fontSize: 24 },
  subtitle: { color: "#666" },
  actions: { display: "flex", gap: 10 },
  refreshBtn: { padding: 8, cursor: "pointer" },
  errorAlert: { color: "red", margin: 10 },
  statsGrid: { display: "flex", gap: 15, margin: 20 },
  statCard: { padding: 15, border: "1px solid #ddd", borderRadius: 10 },
  iconWrapper: { fontSize: 24 },
  sectionCard: { marginTop: 20, padding: 20, border: "1px solid #ddd" },
  table: { width: "100%" },
  loaderContainer: { textAlign: "center", marginTop: 100 },
  spinner: { width: 40, height: 40, border: "5px solid #ccc", borderTop: "5px solid blue", borderRadius: "50%" },
  loaderText: { marginTop: 10 }
};

export default Dashboard;
